import * as M from './model.js';
import * as P from './planner.js';
import * as PC from './teacher-pc.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<i data-lucide="${n}"></i>`;
const btn=(text,action,data='',cls='')=>`<button class="btn ${cls}" data-action="${action}" ${data}>${text}</button>`;
export const APPS={desktop:{name:'바탕화면',icon:'monitor'},classwork:{name:'학급업무',icon:'users-round'},adminwork:{name:'행정업무',icon:'briefcase-business'},stickies:{name:'스티커메모',icon:'sticky-note'},official:{name:'공문함',icon:'inbox'},minutes:{name:'회의록',icon:'notebook-tabs'},roster:{name:'학생명렬표',icon:'contact-round'},files:{name:'내 문서',icon:'folder-open'},messenger:{name:'학교톡',icon:'messages-square'},planner:{name:'개인 일정',icon:'calendar-check'},records:{name:'평가·관찰',icon:'notebook-pen'},notices:{name:'가정통신문',icon:'mail'}};
export function shell(s,app,title,body){const active=APPS[app]||APPS.desktop;return `<div class="pc-shell"><nav class="pc-launcher" aria-label="교사 PC 프로그램">${Object.entries(APPS).map(([id,a])=>`<button data-action="pc-app" data-id="${id}" title="${a.name}" class="${id===app?'active':''}" aria-pressed="${id===app}">${icon(a.icon)}<span>${a.name}</span>${id==='official'&&PC.data(s).official.some(d=>!d.read)?'<b class="pc-dot" aria-label="새 공문"></b>':''}</button>`).join('')}</nav><section class="pc-window"><header class="pc-windowbar">${icon(active.icon)}<b>${esc(title)}</b><span class="pc-save-status" role="status">기기에 저장</span>${app!=='desktop'?'<button data-action="pc-app" data-id="desktop" aria-label="바탕화면으로">'+icon('grid-2x2')+'</button>':''}</header><div class="pc-content">${body}</div></section><footer class="pc-taskbar"><button data-action="pc-app" data-id="desktop">${icon('layout-grid')}<span>교사 PC</span></button><span class="pc-task-current">${esc(active.name)}</span><span class="pc-task-clock"><b>${M.clock(s.minute)}</b><small>${M.dateLabel(s)}</small></span><button data-action="pc-exit" aria-label="교사 PC 닫기">${icon('power')}</button></footer></div>`;}
export function desktop(s){const d=PC.data(s),pending=d.official.filter(x=>x.status!=='completed'),notes=d.notes.filter(n=>!n.archived).sort((a,b)=>Number(b.pinned)-Number(a.pinned)).slice(0,3),meetings=P.data(s).entries.filter(e=>e.type==='meeting'&&e.day>=s.day&&e.status!=='완료').sort((a,b)=>a.day-b.day||a.start-b.start).slice(0,2);return {title:'교사 업무 바탕화면',body:`<div class="pc-welcome"><div><small>${M.REGIONS[s.config.region].school}</small><h3>${esc(s.config.teacherName)} 선생님의 PC</h3></div><span>${s.config.grade}학년 · 근무 08:40–16:40</span></div><div class="pc-home-layout"><div class="pc-desktop-icons">${Object.entries(APPS).filter(([id])=>id!=='desktop').map(([id,a],i)=>`<button data-action="pc-app" data-id="${id}" class="pc-shortcut tone-${i%5}"><span>${icon(a.icon)}</span><b>${a.name}</b>${id==='official'?`<small>미처리 ${pending.length}건</small>`:''}</button>`).join('')}</div><aside class="pc-widgets"><section><h4>오늘 챙길 업무</h4>${pending.slice(0,3).map(x=>`<button class="pc-brief" data-action="pc-official" data-id="${x.id}"><b>${esc(x.title)}</b><small>${M.dateLabel({day:x.due})}까지 · ${PC.statusLabel(x)}</small></button>`).join('')||'<p>공문 처리를 모두 마쳤어요.</p>'}${meetings.map(e=>`<button class="pc-brief" data-action="planner-entry" data-id="${e.id}"><b>${esc(e.title)}</b><small>${M.dateLabel({day:e.day})} ${M.clock(e.start)} · ${M.ROOMS[e.room].name}</small></button>`).join('')}</section><section><h4>책상 위 메모</h4>${notes.map(n=>`<button class="pc-sticky-preview ${n.color}" data-action="pc-note" data-id="${n.id}"><b>${n.pinned?'📌 ':''}${esc(n.title||'메모')}</b><span>${esc(n.text.slice(0,130)||'내용을 적어 주세요.')}</span></button>`).join('')||'<p>떠오른 할 일을 날짜와 함께 적어 두세요.</p>'}${btn('+ 메모 붙이기','pc-note-new')}</section></aside></div>`};}
export function stickies(s,id,trash=false){const notes=PC.data(s).notes.filter(n=>n.archived===trash).sort((a,b)=>Number(b.pinned)-Number(a.pinned)),n=notes.find(n=>n.id===id);return {title:'스티커메모',body:`<div class="pc-toolbar">${btn('+ 새 메모','pc-note-new','','primary')}${btn(trash?'메모로 돌아가기':'보관함','pc-note-list',`data-trash="${!trash}"`)}<span>${notes.length}개 · 개인 메모</span></div><div class="pc-note-grid">${notes.map(x=>`<button class="pc-sticky-preview ${x.color} ${x.id===id?'selected':''}" data-action="pc-note" data-id="${x.id}"><b>${x.pinned?'📌 ':''}${esc(x.title||'메모')}</b><span>${esc(x.text.slice(0,150)||'내용 없음')}</span><small>${esc(x.created)}</small></button>`).join('')||'<p class="empty">아직 메모가 없습니다.</p>'}</div>${n?`<form class="pc-note-editor ${n.color}" data-pc-note="${n.id}"><label for="pc-note-title">메모 제목</label><input id="pc-note-title" maxlength="60" value="${esc(n.title)}"><label for="pc-note-text">내용</label><textarea id="pc-note-text" maxlength="2000" rows="7" placeholder="준비할 자료, 확인할 약속…">${esc(n.text)}</textarea><div class="pc-note-colors">${PC.NOTE_COLORS.map(c=>`<button type="button" class="${c} ${n.color===c?'selected':''}" data-action="pc-note-color" data-id="${n.id}" data-color="${c}" aria-label="${{yellow:'노란색',blue:'파란색',pink:'분홍색',green:'녹색'}[c]} 메모" aria-pressed="${n.color===c}"></button>`).join('')}</div><small>작성 ${esc(n.created)}<br>수정 ${esc(n.updated)} · 입력 내용 자동 저장</small></form><div class="buttons">${btn(n.pinned?'고정 해제':'바탕화면에 고정','pc-note-pin',`data-id="${n.id}"`)}${btn(n.archived?'다시 꺼내기':'보관함으로','pc-note-archive',`data-id="${n.id}"`)}</div>`:'<div class="notice">메모를 고르면 내용을 수정할 수 있습니다. 개인 메모를 적는 것만으로 학생 평가나 NPC 관계가 바뀌지는 않습니다.</div>'}`};}
export function official(s,id,filter='pending'){const docs=PC.data(s).official,doc=docs.find(d=>d.id===id);if(!doc){const list=docs.filter(d=>filter==='all'||filter==='completed'?filter==='all'||d.status==='completed':d.status!=='completed');return {title:'공문함',body:`<nav class="category-tabs">${[['pending','미처리'],['completed','처리 완료'],['all','전체 공문']].map(([f,t])=>btn(t,'pc-official-filter',`data-id="${f}"`,filter===f?'soft':'')).join('')}</nav><div class="pc-mail-list">${list.slice().reverse().map(d=>`<button class="pc-mail-row ${!d.read?'unread':''}" data-action="pc-official" data-id="${d.id}"><span class="pc-doc-icon">${icon(d.kind==='report'?'file-pen-line':'mail-open')}</span><span><b>${esc(d.title)}</b><small>${esc(d.from)} · ${esc(d.number)} · ${d.kind==='report'?'제출 요청':'안내 공람'}</small></span><span class="pc-doc-state"><b class="status-${d.status}">${PC.statusLabel(d)}</b><small>${d.due<s.day&&d.status!=='completed'?'기한 지남 · ':''}${M.dateLabel({day:d.due})}까지</small></span></button>`).join('')||'<div class="empty">이 문서함에 공문이 없습니다.</div>'}</div><div class="notice">공문 마감은 개인 일정에도 표시됩니다. 기안 상신 5분, 최종 제출·공람 처리 2분이 필요합니다.</div>`};}
 const editable=!['submitted','approved','completed'].includes(doc.status),files=PC.data(s).files.filter(f=>!f.archived);return {title:doc.title,body:`<div class="pc-toolbar">${btn('공문 목록','pc-app','data-id="official"')}<b class="status-${doc.status}">${PC.statusLabel(doc)}</b><span>${M.dateLabel({day:doc.due})}까지</span></div><article class="pc-paper"><div class="pc-paper-org">${M.REGIONS[s.config.region].school}</div><dl class="pc-paper-meta"><dt>문서번호</dt><dd>${esc(doc.number)}</dd><dt>보낸 곳</dt><dd>${esc(doc.from)}</dd><dt>수신</dt><dd>${s.config.grade}학년 담임</dd><dt>접수</dt><dd>${esc(doc.received)}</dd></dl><h3>${esc(doc.title)}</h3><p>${esc(doc.body)}</p></article>${doc.feedback?`<div class="notice ${doc.status==='revision'?'amber':''}"><b>한정우 교감 · ${doc.status==='revision'?'보완 의견':'검토 결과'}</b><p>${esc(doc.feedback)}</p></div>`:''}${doc.kind==='report'?`<form class="pc-draft" data-pc-draft="${doc.id}"><label for="pc-reply">기안 내용</label><textarea id="pc-reply" maxlength="3000" rows="6" ${editable?'':'readonly'} placeholder="요청한 내용을 확인하고 제출할 자료와 적용할 활동을 적어 주세요.">${esc(doc.reply)}</textarea><h4>붙임 문서 · ${PC.FILE_KINDS[doc.required]} 필요</h4><div class="pc-attachments">${files.map(f=>`<label><input type="checkbox" class="pc-attachment" value="${f.id}" ${doc.attachments.includes(f.id)?'checked':''} ${editable?'':'disabled'}><span>${icon('file-text')} ${esc(f.title)}<small>${PC.FILE_KINDS[f.kind]} · ${esc(f.updated)}</small></span></label>`).join('')||'<p>내 문서에서 자료를 먼저 만들어 주세요.</p>'}</div></form><div class="pc-approval-line"><span>기안 · ${esc(s.config.teacherName)}</span><span>검토 · 한정우 교감</span><span>최종 제출 · 담당 부서</span></div><div class="buttons">${editable?btn('필요한 붙임 만들기','pc-required-file',`data-id="${doc.id}"`)+btn('기안 저장','pc-draft-save',`data-id="${doc.id}"`)+btn('결재 올리기 · 5분','pc-submit',`data-id="${doc.id}"`,'primary'):''}${doc.status==='submitted'?btn('검토 기다리기','pc-review',`data-id="${doc.id}"`):''}${doc.status==='approved'?btn('최종 제출 · 2분','pc-finish',`data-id="${doc.id}"`,'primary'):''}</div>`:doc.status!=='completed'?`<div class="buttons">${btn('안내 확인·공람 완료 · 2분','pc-finish',`data-id="${doc.id}"`,'primary')}</div>`:''}<details class="pc-history"><summary>처리 이력 ${doc.history.length}건</summary>${doc.history.map(h=>`<p><small>${esc(h.date)}</small>${esc(h.text)}</p>`).join('')}</details>`};
}
export function files(s,id){const list=PC.data(s).files.filter(f=>!f.archived),f=list.find(f=>f.id===id);return {title:f?f.title:'내 문서',body:`<div class="pc-toolbar">${Object.entries(PC.FILE_KINDS).filter(([id])=>id!=='minutes').map(([id,t])=>btn('+ '+t,'pc-file-new',`data-id="${id}"`)).join('')}${f?btn('문서 목록','pc-app','data-id="files"'):''}</div>${f?`<form class="pc-file-editor" data-pc-file="${f.id}"><label for="pc-file-title">문서 제목</label><input id="pc-file-title" maxlength="100" value="${esc(f.title)}"><div class="pc-document-meta">${PC.FILE_KINDS[f.kind]} · 작성 ${esc(f.created)}<br>수정 ${esc(f.updated)} · 입력 내용 자동 저장</div><label for="pc-file-body">문서 내용</label><textarea id="pc-file-body" rows="18" maxlength="12000" spellcheck="false">${esc(f.body)}</textarea></form><div class="buttons">${btn('문서 저장','pc-file-save',`data-id="${f.id}"`,'primary')}${btn('텍스트 파일로 내려받기','pc-file-export',`data-id="${f.id}"`)}${btn('공문에 첨부하러 가기','pc-app','data-id="official"')}</div>`:`<div class="pc-file-list">${list.map(f=>`<button data-action="pc-file" data-id="${f.id}">${icon(f.kind==='roster'?'table-2':f.kind==='minutes'?'notebook-tabs':'file-text')}<span><b>${esc(f.title)}</b><small>${PC.FILE_KINDS[f.kind]} · ${esc(f.updated)}</small></span></button>`).join('')||'<p class="empty">계획서·명렬표·수업자료 또는 빈 문서를 만들어 보세요.</p>'}</div>`}`};}
export function minutes(s){const list=P.data(s).entries.filter(e=>e.type==='meeting'&&e.status==='완료').sort((a,b)=>b.day-a.day||b.start-a.start);return {title:'회의록',body:`<div class="notice">실제로 참석한 회의의 일시·장소·안건·협의 내용과 후속 준비를 불러옵니다. 문서로 만들면 내 문서에서 보완할 수 있습니다.</div><div class="pc-file-list">${list.map(e=>`<button data-action="pc-minute" data-id="${e.id}">${icon('notebook-tabs')}<span><b>${esc(e.title)}</b><small>${M.dateLabel({day:e.day})} ${M.clock(e.start)} · ${M.ROOMS[e.room].name}</small><small>${esc(e.note.slice(0,100))}</small></span></button>`).join('')||'<div class="empty">아직 참석 기록이 없습니다. 개인 일정에서 회의 장소와 시간을 확인해 주세요.</div>'}</div><div class="buttons">${btn('회의 일정 확인','pc-app','data-id="planner"')}</div>`};}
export function roster(s,portrait){return {title:'학생명렬표',body:`<div class="pc-toolbar"><b>${s.config.grade}학년 · ${s.students.length}명</b><span>${M.dateLabel(s)} 기준</span>${btn('명렬표 문서 만들기','pc-file-new','data-id="roster"','primary')}${btn('출결 확인','attendance')}</div><div class="table-scroll"><table class="data-table pc-roster"><thead><tr><th>번호</th><th>학생</th><th>성별</th><th>오늘 출결</th><th>1인 1역</th></tr></thead><tbody>${s.students.map((st,i)=>`<tr><td>${i+1}</td><td><button data-action="profile" data-id="${st.id}" class="table-person">${portrait(st.id,'xs')}<b>${st.name}</b></button></td><td>${st.gender}</td><td>${M.attend(s,st.id)}</td><td>${esc(st.role)}</td></tr>`).join('')}</tbody></table></div>`};}
